/* MODULE tp03 · Bước 4 Tạo thông điệp · Tên, câu slogan và lời hứa thương hiệu
   9 bài × 7 câu. Thương hiệu thật chỉ là ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau.
   Không khẳng định nội dung luật: chuyện nhãn hiệu chỉ nói là cần tra cứu, hỏi người có chuyên môn. */
BAI_ADD({ mod:'tp03', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tp03-01', skill:'brand', read:'6 phút', t:'Tên mô tả, tên gợi hình hay tên tự đặt: chọn loại nào cho quán mới?',
  situation:'Hai vợ chồng chuẩn bị mở quán bún chả ở Cầu Giấy, vốn khoảng 400 triệu, gần như không có tiền quảng cáo. Ba cái tên trên bàn: "Bún Chả Hà Nội Gốc" (nói thẳng bán gì), "Khói Than" (gợi cảm giác nướng than), và "Bunza" (tự đặt, không có nghĩa). Người chồng thích Bunza vì nghe hiện đại.',
  concept:{ name:'Phổ tên: mô tả – gợi hình – tự đặt',
    body:'<b>Tên mô tả</b> nói luôn sản phẩm là gì: khách hiểu ngay, không tốn tiền giải thích, nhưng khó phân biệt vì đối thủ cũng dùng được chữ tương tự. <b>Tên tự đặt</b> (như Vinamilk ghép từ chữ, hay một từ vô nghĩa) dễ sở hữu riêng nhưng lúc đầu rỗng nghĩa — phải có tiền và thời gian để lấp nghĩa vào. <b>Tên gợi hình</b> nằm giữa: gợi một cảm giác liên quan, đủ riêng để nhớ, đủ gần để đoán. Chọn loại nào phụ thuộc vào ngân sách giải thích bạn có.' },
  example:'Quán không có tiền quảng cáo, khách chủ yếu là người đi ngang. "Bunza" bắt khách phải đọc thêm biển phụ mới biết bán gì — với ngân sách gần bằng không, đó là cái giá quá đắt. "Bún Chả Hà Nội Gốc" dễ hiểu nhưng trên cùng con phố có thể đã có ba biển na ná. "Khói Than" gợi đúng thứ khách ngửi thấy từ vỉa hè, kèm dòng phụ "bún chả nướng than hoa" là đủ hiểu và vẫn có chữ riêng để nhớ.',
  takeaway:'Tên càng ít nghĩa càng dễ sở hữu nhưng càng tốn tiền giải thích; chọn theo ngân sách, không theo sở thích.',
  apply:'Lấy tên thương hiệu bạn đang làm, xếp nó vào một trong ba loại, rồi nói trong 60 giây: bạn đang trả giá gì cho loại tên đó.',
  mistakes:['Chọn tên tự đặt "cho sang" khi không có tiền để dạy khách tên đó nghĩa là gì.','Chọn tên mô tả thuần tuý rồi ngạc nhiên vì khách nhầm với quán bên cạnh.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với một quán nhỏ gần như không có ngân sách quảng cáo, loại tên nào thường gây bất lợi nhất lúc mới mở?',
    options:[{k:'a',t:'Tên mô tả nói thẳng món, vì nghe quá bình thường, dễ bị chê quê'},{k:'b',t:'Tên tự đặt không có nghĩa, vì khách không đoán được bán gì'},
             {k:'c',t:'Tên gợi hình, vì nằm lưng chừng nên chẳng ai nhớ nổi'},{k:'d',t:'Tên có chữ Hà Nội, vì khách miền Bắc nghe đã thấy nhàm'}],
    answer:'b', why:{a:'Tên mô tả có nhược điểm là khó phân biệt, nhưng nó không bắt khách đoán — với quán không có tiền giải thích, đó là lợi thế.',
      b:'Đúng. Tên rỗng nghĩa cần được lấp nghĩa bằng quảng cáo và thời gian; quán nhỏ không có cả hai.',
      c:'Tên gợi hình thường là điểm cân bằng: đủ riêng để nhớ, đủ gần để đoán.',
      d:'Chữ địa danh có thể phổ biến, nhưng không phải là thứ khiến khách không hiểu quán bán gì.'} },
  { type:'mcq', stem:'Nếu là người tư vấn cho hai vợ chồng, bạn chọn cách đặt tên nào?',
    options:[{k:'a',t:'"Khói Than" kèm dòng phụ nói rõ món — riêng mà vẫn dễ hiểu'},{k:'b',t:'"Bunza" vì người chồng thích và nghe hiện đại, hợp giới trẻ'},
             {k:'c',t:'"Bún Chả Hà Nội Gốc" vì càng rõ càng tốt, không cần khác biệt gì'},{k:'d',t:'Để trống biển tên, mở bán một tháng rồi đặt theo cách khách tự gọi'}],
    answer:'a', why:{a:'Đúng. Tên gợi hình cho một chữ riêng để nhớ; dòng phụ gánh phần giải thích mà quán không có tiền để quảng cáo.',
      b:'Sở thích của chủ không trả được chi phí dạy khách một từ vô nghĩa.',
      c:'Rõ thì tốt, nhưng khi cả phố có biển na ná, khách khó nhớ đã ăn ở quán nào để quay lại.',
      d:'Khách không có gì để gọi thì sẽ gọi theo địa chỉ; một tháng đầu mất cơ hội được nhớ.'} },
  { type:'mcq', stem:'Vì sao tên mô tả thuần tuý (ví dụ "Cà Phê Muối Ngon") thường khó được nhớ riêng?',
    options:[{k:'a',t:'Vì tên mô tả luôn dài hơn tên tự đặt nên khách lười đọc hết'},{k:'b',t:'Vì khách không tin những quán tự khen mình ngon ngay trên biển'},
             {k:'c',t:'Vì đối thủ cũng dùng được những chữ đó, nên tên không chỉ về riêng ai'},{k:'d',t:'Vì tên tiếng Việt có dấu nên khó tìm trên mạng hơn tên không dấu'}],
    answer:'c', why:{a:'Độ dài không phải vấn đề chính; có tên mô tả rất ngắn vẫn khó nhớ riêng.',
      b:'Chữ "ngon" có thể bị nghi, nhưng vấn đề gốc là mọi quán cà phê muối đều nói được câu đó.',
      c:'Đúng. Chữ chung của ngành không thuộc về ai; khách nhớ món chứ không nhớ quán.',
      d:'Chuyện dấu là vấn đề kỹ thuật tìm kiếm, không giải thích vì sao tên khó được nhớ riêng.'} },
  { type:'mcq', stem:'Một hãng mỹ phẩm có ngân sách lớn, định bán nhiều dòng sản phẩm trong mười năm tới. Tên tự đặt có lợi gì cho họ?',
    options:[{k:'a',t:'Khách hiểu ngay sản phẩm là gì nên không cần quảng cáo nhiều'},{k:'b',t:'Được tự động bảo hộ vì không trùng với từ nào trong từ điển'},
             {k:'c',t:'Giúp hãng bán giá cao hơn ngay từ ngày đầu nhờ nghe như hàng ngoại'},{k:'d',t:'Không gắn chặt vào một món, nên mở rộng sang dòng khác không bị vướng'}],
    answer:'d', why:{a:'Ngược lại: tên tự đặt không nói gì lúc đầu, nên cần quảng cáo để lấp nghĩa.',
      b:'Tên lạ có thể dễ đăng ký hơn, nhưng không có gì là "tự động"; vẫn phải tra cứu và làm thủ tục.',
      c:'Giá cao đến từ sản phẩm và cách xây thương hiệu, không đến từ một cái tên lạ tai.',
      d:'Đúng. Tên không mô tả món nào nên chứa được nhiều dòng; hãng có tiền để lấp nghĩa theo thời gian.'} },
  { type:'mcq', stem:'Tiệm giặt ủi tên "Giặt Sạch 24h" mở thêm dịch vụ vệ sinh sofa và rèm. Rủi ro của cái tên lúc này là gì?',
    options:[{k:'a',t:'Tên gắn với giặt đồ nên khách khó nghĩ tới tiệm khi cần vệ sinh sofa'},{k:'b',t:'Tên có số nên máy tìm kiếm không đọc được, khách không tìm ra tiệm'},
             {k:'c',t:'Khách sẽ đòi mọi dịch vụ mới cũng phải xong trong 24 giờ như giặt đồ'},{k:'d',t:'Tên quá ngắn nên không đủ chỗ để thêm chữ sofa và rèm vào biển'}],
    answer:'a', why:{a:'Đúng. Tên mô tả nhốt thương hiệu vào đúng thứ nó mô tả; mở rộng thì phải tốn công giải thích lại.',
      b:'Máy tìm kiếm đọc được chữ số bình thường; vấn đề là ý nghĩa của tên.',
      c:'Có thể có kỳ vọng về tốc độ, nhưng rủi ro chính là khách không nghĩ tới tiệm cho nhu cầu mới.',
      d:'Biển có thể thêm dòng phụ; vấn đề nằm ở trí nhớ của khách chứ không ở diện tích biển.'} },
  { type:'mcq', stem:'Tên nào dưới đây là tên gợi hình (không mô tả thẳng, cũng không vô nghĩa)?',
    options:[{k:'a',t:'"Tiệm Sửa Điện Thoại Minh Anh" cho một tiệm sửa điện thoại'},{k:'b',t:'"Mây" cho một thương hiệu gối và chăn'},
             {k:'c',t:'"Xolvik" cho một thương hiệu nước rửa chén mới'},{k:'d',t:'"Trà Sữa Trân Châu Đường Đen" cho một quán trà sữa'}],
    answer:'b', why:{a:'Đây là tên mô tả kèm tên người: nói thẳng dịch vụ là gì.',
      b:'Đúng. "Mây" không nói gối, nhưng gợi cảm giác mềm, nhẹ — đúng thứ người mua gối tìm.',
      c:'Đây là tên tự đặt: không mang nghĩa sẵn, phải được lấp nghĩa sau.',
      d:'Đây là tên mô tả thuần tuý: liệt kê đúng món, quán nào cũng dùng được.'} },
  { type:'mcq', stem:'Chủ một thương hiệu nước mắm nói: "Tên mô tả an toàn nhất vì ai cũng hiểu". Điểm nào trong câu này cần xem lại?',
    options:[{k:'a',t:'Tên mô tả khó đọc hơn các loại tên khác nên không hề an toàn'},{k:'b',t:'Nước mắm là ngành truyền thống nên bắt buộc phải dùng tên tự đặt'},
             {k:'c',t:'Dễ hiểu chưa đủ: khách phải nhớ và phân biệt được bạn với hãng khác'},{k:'d',t:'Tên mô tả chỉ hợp với dịch vụ, không hợp với hàng đóng chai trên kệ'}],
    answer:'c', why:{a:'Tên mô tả thường dễ đọc; vấn đề không nằm ở cách đọc.',
      b:'Không có quy tắc bắt buộc nào như vậy; nhiều hãng nước mắm dùng tên gắn với địa danh hoặc gia đình.',
      c:'Đúng. An toàn về hiểu nhưng rủi ro về nhớ: tên chung thì doanh số dễ chảy sang hãng nào nằm gần trên kệ.',
      d:'Tên mô tả dùng được cho cả hàng lẫn dịch vụ; vấn đề là mức độ phân biệt.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tp03-02', skill:'brand', read:'7 phút', t:'Tên đã chọn xong — kiểm tra gì trước khi in biển và làm bao bì?',
  situation:'Một thương hiệu bánh tráng trộn đóng gói ở TP.HCM chọn tên "Quýnh" vì vui tai. Trước khi đặt in 5.000 túi, bạn cho 40 người nghe tên qua điện thoại rồi nhờ gõ lại: chỉ 14 người gõ đúng, số còn lại gõ "Quýn", "Quỳnh", "Quinh". Fanpage tên "Quýnh" cũng đã có người dùng.',
  concept:{ name:'Năm phép thử một cái tên',
    body:'Trước khi tiêu tiền cho biển và bao bì, cho tên qua năm phép thử. <b>Nghe – viết</b>: đọc qua điện thoại, người nghe có gõ lại đúng không. <b>Gõ không dấu</b>: khách tìm trên mạng thường gõ không dấu, ra kết quả gì. <b>Tên miền và fanpage</b>: còn trống không. <b>Tra cứu nhãn hiệu</b>: đã có ai đăng ký tên giống hoặc gần giống trong cùng nhóm hàng chưa — việc này cần tra ở cơ sở dữ liệu chính thức hoặc hỏi người có chuyên môn, không đoán. <b>Nghĩa ngoài ý muốn</b>: ở vùng miền khác hoặc tiếng lóng, tên có nghĩa xấu không.' },
  example:'Phép nghe – viết cho kết quả 14 trên 40, tức 35% gõ đúng: cứ ba khách nghe bạn bè giới thiệu thì hai người tìm sai tên. Gõ không dấu "quynh" ra hàng loạt tên người. Fanpage đã có chủ. Ba phép thử trượt trước khi đụng tới chuyện nhãn hiệu. Đổi tên lúc này tốn một buổi họp; đổi sau khi in 5.000 túi thì tốn tiền in lại cộng toàn bộ khách đã nhớ tên cũ.',
  takeaway:'Tên phải qua được tai, bàn phím và tra cứu trước khi qua được máy in.',
  apply:'Đọc tên thương hiệu bạn đang làm cho ba người qua điện thoại, nhờ họ gõ lại. Nói trong 60 giây: bao nhiêu người gõ đúng, và họ sai ở đâu.',
  mistakes:['Chỉ hỏi "tên này hay không" mà không thử khách có gõ lại được không.','Tự kết luận "chưa ai đăng ký" sau khi tìm Google vài phút, không tra cứu đúng nơi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: phép thử nào thường bị bỏ qua nhất khi chủ shop tự đặt tên?',
    options:[{k:'a',t:'Hỏi bạn bè xem tên nghe có hay, có sang không'},{k:'b',t:'Chọn màu và phông chữ để viết tên lên logo'},
             {k:'c',t:'Kiểm tra tên có đẹp khi in trên áo đồng phục nhân viên không'},{k:'d',t:'Đọc tên qua điện thoại xem người nghe có viết lại đúng không'}],
    answer:'d', why:{a:'Đây là việc gần như ai cũng làm — và là phép thử yếu nhất.',
      b:'Logo thường được làm rất kỹ; nhưng đó là việc sau khi tên đã chốt.',
      c:'Đồng phục là chi tiết phụ, ít ảnh hưởng tới việc khách tìm ra bạn.',
      d:'Đúng. Khách giới thiệu nhau bằng lời; tên nghe xong không viết lại được là mất khách ở bước tìm kiếm.'} },
  { type:'mcq', stem:'Tên "Quýnh" trượt phép nghe – viết, fanpage đã có chủ, nhưng chủ shop rất thích. Bạn đề xuất làm gì trước khi in?',
    options:[{k:'a',t:'Cứ in theo kế hoạch, rồi chạy quảng cáo thật nhiều để khách tự quen dần với cách viết đúng'},{k:'b',t:'Giữ tinh thần vui của tên, tìm vài phương án khác và cho qua đủ năm phép thử'},
             {k:'c',t:'Giữ tên, chỉ thêm dấu gạch ngang "Quý-nh" để khách dễ đọc hơn'},{k:'d',t:'Mua lại fanpage từ người đang dùng rồi giữ nguyên tên như cũ'}],
    answer:'b', why:{a:'Quảng cáo có thể dạy cách viết, nhưng tốn tiền cho một lỗi sửa được miễn phí lúc này.',
      b:'Đúng. Giữ cái chủ shop thích (sự vui tai) nhưng chọn một tên qua được tai, bàn phím và tra cứu.',
      c:'Thêm ký tự lạ thường làm việc gõ khó hơn, không dễ hơn.',
      d:'Mua fanpage chỉ giải một phép thử; khách vẫn gõ sai tên, và chưa ai tra cứu nhãn hiệu.'} },
  { type:'calc', stem:'Bạn đọc tên cho 40 người qua điện thoại, 14 người gõ lại đúng. Tỉ lệ gõ đúng là bao nhiêu phần trăm?',
    unit:'%', ans:35, tol:0.1, wrong:[[65,'SAI_TINH_TOAN'],[285.7,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Tỉ lệ gõ đúng = số người gõ đúng ÷ tổng số người nghe.','14 ÷ 40 = 0,35 = <b>35%</b>.'] },
  { type:'mcq', stem:'Bạn tìm Google tên mới, không thấy doanh nghiệp nào dùng. Kết luận nào hợp lý?',
    options:[{k:'a',t:'Chưa đủ: vẫn cần tra cứu nhãn hiệu ở nơi chính thức hoặc hỏi người có chuyên môn'},{k:'b',t:'Tên đã an toàn về mặt nhãn hiệu, có thể in bao bì ngay hôm nay'},
             {k:'c',t:'Tên an toàn nếu mình đăng fanpage trước, vì ai dùng trước là của người đó'},{k:'d',t:'Chỉ cần đổi một chữ cái so với tên có sẵn là chắc chắn không bị trùng'}],
    answer:'a', why:{a:'Đúng. Google chỉ cho thấy ai đang hiện diện trên mạng; đơn đăng ký nhãn hiệu nằm ở cơ sở dữ liệu khác.',
      b:'Không thấy trên Google không có nghĩa là chưa ai đăng ký tên đó cho cùng nhóm hàng.',
      c:'Có fanpage trước không phải là cơ sở để khẳng định quyền với cái tên; đừng đoán quy định.',
      d:'Tên gần giống vẫn có thể gây nhầm lẫn; không có mẹo đổi một chữ để chắc chắn an toàn.'} },
  { type:'mcq', stem:'Một thương hiệu nước uống ở Hà Nội định mở ra miền Nam, nhưng tên có một từ mang nghĩa tục trong tiếng lóng miền Nam. Phép thử nào lẽ ra đã bắt được lỗi này?',
    options:[{k:'a',t:'Phép thử gõ không dấu trên thanh tìm kiếm'},{k:'b',t:'Phép thử tên miền và fanpage còn trống'},
             {k:'c',t:'Phép thử nghĩa ngoài ý muốn ở vùng miền khác và tiếng lóng'},{k:'d',t:'Phép thử đọc qua điện thoại cho người ở cùng thành phố'}],
    answer:'c', why:{a:'Gõ không dấu kiểm việc tìm kiếm, không kiểm nghĩa.',
      b:'Tên miền còn trống không nói gì về nghĩa của tên.',
      c:'Đúng. Hỏi vài người ở vùng miền và độ tuổi khác là cách rẻ nhất để bắt nghĩa xấu.',
      d:'Người cùng thành phố thường hiểu như bạn; họ không bắt được nghĩa lóng ở vùng khác.'} },
  { type:'mcq', stem:'Vì sao phép "gõ không dấu" quan trọng với tên tiếng Việt?',
    options:[{k:'a',t:'Vì tên có dấu không đăng ký được làm tên doanh nghiệp'},{k:'b',t:'Vì máy in bao bì thường làm mất dấu nên phải chuẩn bị bản không dấu'},
             {k:'c',t:'Vì khách trẻ không thích tên có dấu, thấy nghe quê'},{k:'d',t:'Vì nhiều người tìm trên mạng bằng chữ không dấu, và tên có thể trùng thứ khác'}],
    answer:'d', why:{a:'Đừng khẳng định quy định mà chưa tra; và đây không phải lý do của phép thử.',
      b:'Máy in không phải vấn đề; phép thử này nói về hành vi tìm kiếm của khách.',
      c:'Sở thích về dấu khác nhau tuỳ người; không phải lý do kỹ thuật cần kiểm.',
      d:'Đúng. "Quýnh" không dấu thành "quynh" — trùng tên người, kết quả tìm kiếm bị lấp.'} },
  { type:'mcq', stem:'Chủ shop hỏi: "Năm phép thử tốn thời gian, làm cái nào trước?" Thứ tự nào hợp lý nhất?',
    options:[{k:'a',t:'Tra cứu nhãn hiệu trước tiên, vì đó là phép thử tốn kém và lâu nhất'},{k:'b',t:'Các phép rẻ và nhanh trước để loại bớt, tra nhãn hiệu cho vài tên còn lại'},
             {k:'c',t:'Làm logo trước để khách hình dung, rồi mới kiểm tra các phép còn lại'},{k:'d',t:'Chỉ cần kiểm fanpage, vì bán online thì fanpage là thứ duy nhất quan trọng'}],
    answer:'b', why:{a:'Tra cứu kỹ cho mười tên là lãng phí khi phần lớn sẽ trượt phép nghe – viết trong năm phút.',
      b:'Đúng. Loại nhanh bằng tai và bàn phím, rồi dồn công tra cứu cho số ít tên đáng giữ.',
      c:'Làm logo trước khiến mọi người gắn bó với một tên chưa qua kiểm tra.',
      d:'Fanpage chỉ là một phép; tên trùng nhãn hiệu hay gõ sai vẫn làm hỏng việc bán online.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tp03-03', skill:'brand', read:'6 phút', t:'Tên tiếng Anh hay tiếng Việt cho một thương hiệu Việt?',
  situation:'Một xưởng làm bánh pía và bánh trung thu ở Sóc Trăng muốn ra hộp quà cao cấp bán ở TP.HCM và gửi biếu Việt kiều. Nhóm trẻ trong công ty muốn đặt tên "Golden Moon Bakery" cho "sang". Người sáng lập muốn giữ tên gia đình "Bà Sáu". Khách chính là người Việt mua làm quà.',
  concept:{ name:'Ngôn ngữ của tên là một lời hứa về nguồn gốc',
    body:'Ngôn ngữ của tên nói với khách <b>hàng này từ đâu tới</b>. Tên tiếng Anh gợi hiện đại, quốc tế — hợp khi khách chờ đợi điều đó (đồ công nghệ, thời trang theo xu hướng). Tên tiếng Việt gợi gốc gác, truyền thống, tay nghề — hợp khi nguồn gốc chính là lý do khách mua. Chọn sai, tên nói ngược với sản phẩm: một món đặc sản mang tên tiếng Anh chung chung thì mất đúng thứ khiến nó đáng tiền. Câu hỏi đúng không phải "tiếng nào sang hơn" mà "khách mua vì điều gì".' },
  example:'Khách mua bánh pía làm quà vì nó là đặc sản Sóc Trăng, làm theo kiểu gia đình. "Golden Moon Bakery" có thể là tên của bất kỳ tiệm bánh nào ở bất kỳ nước nào — nó xoá đi đúng lý do mua. "Bà Sáu" kể ngay một câu chuyện: có người thật, có nghề. Cái "sang" nhóm trẻ muốn nên nằm ở hộp, giấy, cách in — không cần đổi ngôn ngữ của tên.',
  takeaway:'Hỏi khách mua vì điều gì, rồi chọn ngôn ngữ của tên nói đúng điều đó.',
  apply:'Nghĩ về một thương hiệu Việt dùng tên tiếng Anh. Nói trong 60 giây: cái tên đó đang hứa về nguồn gốc gì, và có khớp lý do khách mua không.',
  mistakes:['Đặt tên tiếng Anh chỉ để trông "sang" khi lý do mua là gốc gác Việt.','Dùng tên tiếng Anh mà người Việt đọc sai, khiến khách ngại gọi tên khi giới thiệu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khi chọn tên tiếng Anh hay tiếng Việt, câu hỏi nào nên đặt ra đầu tiên?',
    options:[{k:'a',t:'Tiếng nào nghe sang hơn trong mắt khách trẻ ở thành phố'},{k:'b',t:'Tiếng nào dễ đăng ký tên miền .com hơn'},
             {k:'c',t:'Khách mua sản phẩm này vì điều gì, và tên có nói đúng điều đó'},{k:'d',t:'Đối thủ lớn nhất trong ngành đang dùng tên tiếng gì'}],
    answer:'c', why:{a:'"Sang" là cảm giác, có thể tạo bằng thiết kế; không phải tiêu chí đầu tiên.',
      b:'Tên miền là phép thử kỹ thuật, làm sau khi đã rõ hướng.',
      c:'Đúng. Ngôn ngữ của tên là lời hứa về nguồn gốc; nó phải khớp với lý do mua.',
      d:'Nhìn đối thủ giúp tránh trùng, nhưng không trả lời tên của bạn nên hứa điều gì.'} },
  { type:'mcq', stem:'Nếu là marketer của xưởng bánh pía, bạn chọn gì cho dòng hộp quà cao cấp?',
    options:[{k:'a',t:'"Golden Moon Bakery" cho dòng cao cấp, giữ "Bà Sáu" cho hàng thường'},{k:'b',t:'Ghép cả hai thành "Bà Sáu Golden Moon" cho vừa lòng mọi người'},
             {k:'c',t:'Đặt tên tiếng Anh mới hoàn toàn, vì Việt kiều quen đọc tiếng Anh'},{k:'d',t:'Giữ "Bà Sáu", làm cái sang bằng hộp, chất liệu và cách kể nguồn gốc'}],
    answer:'d', why:{a:'Tách tên khiến dòng cao cấp mất đúng câu chuyện gốc gác làm nên giá trị của nó.',
      b:'Tên ghép dài, nói hai lời hứa cùng lúc; khách không biết nên nhớ phần nào.',
      c:'Việt kiều mua bánh pía chính vì nhớ quê; tên tiếng Anh chung chung đi ngược lý do đó.',
      d:'Đúng. Tên giữ lời hứa về nghề và gốc; phần cao cấp thể hiện qua thứ khách cầm trên tay.'} },
  { type:'mcq', stem:'Một startup làm phần mềm quản lý kho cho doanh nghiệp, định bán cả ở Việt Nam và Đông Nam Á. Tên tiếng Anh ở đây có hợp lý không?',
    options:[{k:'a',t:'Hợp lý: khách chờ đợi công cụ hiện đại, và thị trường vượt ra ngoài Việt Nam'},{k:'b',t:'Không hợp lý: thương hiệu Việt thì luôn phải dùng tên tiếng Việt cho có gốc gác rõ'},
             {k:'c',t:'Không hợp lý: doanh nghiệp Việt sẽ không tin phần mềm có tên nước ngoài'},{k:'d',t:'Hợp lý chỉ khi tên đó là một từ tiếng Anh có sẵn trong từ điển phổ thông'}],
    answer:'a', why:{a:'Đúng. Ở đây nguồn gốc không phải lý do mua; tên tiếng Anh nói đúng lời hứa hiện đại và đi xa.',
      b:'Không có luật "luôn phải"; ngôn ngữ tên phụ thuộc vào lý do khách mua.',
      c:'Nhiều doanh nghiệp Việt dùng phần mềm tên tiếng Anh hằng ngày; đây không phải rào cản chính.',
      d:'Tên tự đặt nghe như tiếng Anh cũng được; từ có sẵn còn khó sở hữu riêng hơn.'} },
  { type:'mcq', stem:'Tên tiếng Anh "Thyme & Thistle" cho một quán cơm văn phòng ở quận 3. Rủi ro thực tế nhất là gì?',
    options:[{k:'a',t:'Quán sẽ bị hiểu là nhà hàng Âu và bị đánh giá thấp trên các ứng dụng'},{k:'b',t:'Khách khó đọc, ngại gọi tên khi rủ nhau đi ăn hay gõ tìm trên ứng dụng'},
             {k:'c',t:'Tên tiếng Anh làm tăng chi phí thuê mặt bằng ở trung tâm thành phố'},{k:'d',t:'Khách văn phòng chỉ chọn quán có tên tiếng Việt vì thấy thân thuộc hơn'}],
    answer:'b', why:{a:'Có thể gây hiểu nhầm, nhưng đánh giá thấp là suy đoán; cản trở trực tiếp hơn nằm ở cách đọc.',
      b:'Đúng. Tên không đọc được thì không được nói ra; quán cơm sống nhờ lời rủ rê hằng ngày.',
      c:'Tên không ảnh hưởng tới giá thuê mặt bằng.',
      d:'"Chỉ chọn" là quá tuyệt đối; nhiều quán tên tiếng Anh vẫn đông khách văn phòng.'} },
  { type:'mcq', stem:'Nhóm trẻ nói "tên tiếng Anh mới sang". Cách phản hồi có căn cứ nhất là gì?',
    options:[{k:'a',t:'Đồng ý, vì khách Việt luôn đánh giá hàng có tên nước ngoài cao hơn'},{k:'b',t:'Từ chối, vì tên tiếng Anh sẽ khiến cơ quan quản lý nghi là hàng nhập khẩu'},
             {k:'c',t:'Đồng ý nếu thêm chữ "Premium" vào sau để khách hiểu đây là hàng cao cấp'},{k:'d',t:'Tách hai việc: tên nói lời hứa về gốc, cảm giác sang đến từ thiết kế và giá'}],
    answer:'d', why:{a:'"Luôn" là quá tuyệt đối; với đặc sản, gốc Việt thường mới là thứ đáng tiền.',
      b:'Đây là suy đoán về quy định, không phải lập luận marketing có căn cứ.',
      c:'Thêm "Premium" là tự khen, không tạo ra cảm giác cao cấp thật.',
      d:'Đúng. Sang là trải nghiệm tổng thể; không cần hy sinh lời hứa nguồn gốc để có nó.'} },
  { type:'mcq', stem:'Một thương hiệu thời trang Việt dùng tên tiếng Anh, bán cho giới trẻ thành phố, được khách đọc và nhắc tên dễ dàng. Có nên đổi sang tên tiếng Việt?',
    options:[{k:'a',t:'Chưa cần: tên đang nói đúng lời hứa, khách đọc được và đã nhớ'},{k:'b',t:'Nên đổi ngay, vì thương hiệu Việt dùng tên tiếng Anh là thiếu bản sắc'},
             {k:'c',t:'Nên đổi, vì tên tiếng Việt luôn dễ nhớ hơn tên tiếng Anh với mọi khách'},{k:'d',t:'Nên dịch tên sang tiếng Việt và dùng song song hai tên cho hai nhóm khách'}],
    answer:'a', why:{a:'Đúng. Tên đang làm tốt việc của nó; đổi sẽ xoá đi trí nhớ khách đã tích luỹ.',
      b:'Bản sắc không nằm riêng ở ngôn ngữ tên; đổi vì lý do cảm tính là tự phá tài sản.',
      c:'"Luôn" là sai; khách trẻ thành phố nhớ tên tiếng Anh ngắn gọn rất tốt.',
      d:'Hai tên cho một thương hiệu chia đôi trí nhớ của khách.'} },
  { type:'mcq', stem:'Trường hợp nào tên tiếng Việt có gốc gác rõ nhất là lợi thế?',
    options:[{k:'a',t:'Ứng dụng đặt xe muốn mở rộng ra ba nước trong khu vực'},{k:'b',t:'Thương hiệu tai nghe không dây nhắm tới game thủ trẻ'},
             {k:'c',t:'Nước mắm truyền thống bán cho người mua vì tin vào làng nghề'},{k:'d',t:'Chuỗi cà phê muốn khách nghĩ mình theo phong cách Úc hiện đại'}],
    answer:'c', why:{a:'Khi đi nhiều nước, tên gắn chặt với tiếng Việt có thể khó đọc với khách nước ngoài.',
      b:'Khách tai nghe mua vì công nghệ, không vì gốc Việt.',
      c:'Đúng. Khi nguồn gốc là lý do mua, tên nói rõ gốc gác làm việc thay quảng cáo.',
      d:'Lời hứa ở đây là phong cách nước ngoài; tên tiếng Việt thuần sẽ nói ngược.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tp03-04', skill:'creative', read:'6 phút', t:'Slogan này là một lời hứa hay chỉ là một câu cho vui?',
  situation:'Một chuỗi tiệm sửa xe máy ở Đà Nẵng có năm cửa hàng, đang in lại biển. Slogan cũ: "Chạy là mê". Chủ chuỗi phân vân với câu mới: "Báo giá trước, sửa sau — không phát sinh". Nhân viên thấy câu cũ vui hơn, câu mới "khô như nội quy".',
  concept:{ name:'Slogan là lời hứa có thể kiểm tra',
    body:'Một slogan làm việc tốt khi nó trả lời: <b>chọn chúng tôi thì bạn được gì mà nơi khác không chắc cho bạn</b>. Câu cho vui (chơi chữ, cảm xúc chung) dễ thích nhưng khó nhớ vì sao phải chọn bạn. Lời hứa có thể kiểm tra — khách tự thấy bạn giữ hay không — tạo lý do quay lại. Không phải slogan nào cũng phải khô: câu tốt nhất vừa có nhịp dễ nhớ vừa hứa một điều cụ thể. Nhưng nếu phải chọn, một lời hứa rõ thắng một câu vui rỗng.' },
  example:'Khách sửa xe sợ nhất là bị "vẽ bệnh", sửa xong mới báo giá cao. "Chạy là mê" không chạm vào nỗi sợ đó; tiệm nào cũng dán được. "Báo giá trước, sửa sau — không phát sinh" hứa đúng thứ khách lo, và khách kiểm tra được ngay lần đầu tới. Việc còn lại là làm cho nó có nhịp hơn, ví dụ rút gọn thành "Báo giá trước. Không phát sinh." — vẫn giữ lời hứa, đọc to lên nghe gọn.',
  takeaway:'Slogan tốt hứa một điều khách tự kiểm tra được; câu vui không hứa gì thì chỉ là trang trí.',
  apply:'Đọc slogan của ba thương hiệu bạn hay dùng. Nói trong 60 giây: câu nào là lời hứa kiểm tra được, câu nào chỉ là câu cho vui.',
  mistakes:['Chọn slogan theo độ "hay" trong phòng họp thay vì theo nỗi lo của khách.','Nghĩ lời hứa cụ thể thì bắt buộc phải khô; thực ra vẫn có thể gọt cho có nhịp.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì phân biệt một slogan làm việc với một câu chỉ cho vui?',
    options:[{k:'a',t:'Nó hứa một điều cụ thể mà khách tự kiểm tra được'},{k:'b',t:'Nó có vần hoặc chơi chữ nên người nghe nhớ ngay từ lần đầu'},
             {k:'c',t:'Nó dài đủ để giải thích hết ưu điểm của sản phẩm'},{k:'d',t:'Nó dùng từ tiếng Anh nên có cảm giác chuyên nghiệp'}],
    answer:'a', why:{a:'Đúng. Lời hứa kiểm tra được cho khách lý do chọn và lý do quay lại.',
      b:'Vần giúp nhớ câu, nhưng nhớ câu không có nghĩa là biết vì sao chọn bạn.',
      c:'Slogan dài liệt kê ưu điểm thường khó nhớ và không có trọng tâm.',
      d:'Ngôn ngữ không làm nên lời hứa; câu tiếng Anh rỗng vẫn rỗng.'} },
  { type:'mcq', stem:'Nhân viên chê câu mới "khô như nội quy". Nếu là chủ chuỗi, bạn chọn làm gì?',
    options:[{k:'a',t:'Giữ "Chạy là mê" vì nhân viên thích, tinh thần đội ngũ quan trọng hơn'},{k:'b',t:'Dùng cả hai câu, mỗi cửa hàng tự chọn câu nào hợp với khu vực của mình'},
             {k:'c',t:'Giữ lời hứa báo giá trước, gọt lại câu cho gọn và có nhịp hơn'},{k:'d',t:'Bỏ slogan hẳn, chỉ in tên và số điện thoại cho biển thật rõ ràng'}],
    answer:'c', why:{a:'Câu vui không chạm vào nỗi lo của khách; thích trong nội bộ không đổi được lý do chọn.',
      b:'Năm cửa hàng nói năm kiểu làm chuỗi mất một lời hứa chung để khách nhớ.',
      c:'Đúng. Phần giá trị là lời hứa; phần "khô" là câu chữ — sửa câu chữ, giữ lời hứa.',
      d:'Bỏ slogan là bỏ đi chỗ tốt nhất để nói điều khách lo nhất.'} },
  { type:'mcq', stem:'Câu nào dưới đây là một lời hứa khách tự kiểm tra được?',
    options:[{k:'a',t:'"Nâng tầm phong cách sống" cho một thương hiệu nội thất'},{k:'b',t:'"Giao trong 2 giờ nội thành, trễ hoàn phí ship" cho một shop'},
             {k:'c',t:'"Đam mê từ trái tim" cho một tiệm bánh ngọt'},{k:'d',t:'"Chất lượng hàng đầu, giá cả hợp lý" cho một cửa hàng điện máy'}],
    answer:'b', why:{a:'Không ai đo được "nâng tầm"; đây là tính từ, không phải lời hứa.',
      b:'Đúng. Có con số, có cam kết khi trễ — khách kiểm tra được ngay lần đầu.',
      c:'Cảm xúc chung chung, tiệm nào cũng nói được.',
      d:'"Hàng đầu" và "hợp lý" là tự khen; khách không có cách kiểm chứng.'} },
  { type:'mcq', stem:'"Vietjet — Bay là thích ngay" là câu vui, dễ nhớ. Điều gì khiến một câu vui như vậy vẫn có thể làm việc?',
    options:[{k:'a',t:'Câu vui nào đủ ngắn và có vần thì đều làm việc tốt như lời hứa'},{k:'b',t:'Câu vui chỉ làm việc khi hãng không có đối thủ trực tiếp nào'},
             {k:'c',t:'Nó được lặp lại rất lâu, và ăn khớp với tính cách thương hiệu vui, trẻ'},{k:'d',t:'Câu vui luôn tốt hơn lời hứa cụ thể vì khách ghét bị giảng giải'}],
    answer:'c', why:{a:'Ngắn và có vần là điều kiện cần cho trí nhớ, không đủ để thành lý do chọn.',
      b:'Ngành hàng không có nhiều đối thủ; điều kiện này không đúng.',
      c:'Đúng. Câu vui làm việc khi nó là tiếng nói nhất quán của một tính cách, được lặp đủ lâu.',
      d:'"Luôn" là sai; với ngành khách đang lo lắng, lời hứa cụ thể thường mạnh hơn.'} },
  { type:'mcq', stem:'Một phòng khám nha khoa chọn slogan "Nụ cười rạng rỡ". Góp ý nào hữu ích nhất?',
    options:[{k:'a',t:'Câu hay rồi, chỉ cần đổi phông chữ cho mềm mại và dễ đọc hơn'},{k:'b',t:'Nên thêm chữ "tận tâm" và "chuyên nghiệp" vào cho đủ ý của phòng khám'},
             {k:'c',t:'Nên đổi sang tiếng Anh để hợp với khách trẻ thành phố và nghe cao cấp, chuyên nghiệp hơn'},{k:'d',t:'Phòng khám nào cũng nói được; nên hứa điều khách đang lo, ví dụ không đau hay báo giá rõ'}],
    answer:'d', why:{a:'Phông chữ không sửa được một câu không hứa gì.',
      b:'Thêm tính từ tự khen chỉ làm câu dài hơn mà vẫn chung chung.',
      c:'Đổi ngôn ngữ không thêm lời hứa nào.',
      d:'Đúng. Khách đi nha khoa lo đau và lo chi phí; lời hứa chạm vào đó mới là lý do chọn.'} },
  { type:'mcq', stem:'Vì sao lời hứa "kiểm tra được" lại tạo lý do quay lại?',
    options:[{k:'a',t:'Vì khách thấy bạn giữ lời thật, niềm tin tăng sau mỗi lần dùng'},{k:'b',t:'Vì câu cụ thể thì dài hơn nên khách đọc lâu hơn và nhớ lâu hơn'},
             {k:'c',t:'Vì có con số trong câu nên khách nghĩ đó là cam kết có hiệu lực pháp lý'},{k:'d',t:'Vì khách thích so sánh và sẽ quay lại để tìm ra lỗi của thương hiệu'}],
    answer:'a', why:{a:'Đúng. Mỗi lần lời hứa được giữ là một bằng chứng; bằng chứng cộng dồn thành niềm tin.',
      b:'Độ dài không phải cơ chế; một câu cụ thể có thể rất ngắn.',
      c:'Đừng khẳng định hiệu lực pháp lý; cơ chế ở đây là niềm tin từ trải nghiệm.',
      d:'Khách không quay lại để bắt lỗi; họ quay lại vì trải nghiệm đúng như được hứa.'} },
  { type:'mcq', stem:'Tiệm sửa xe gọt câu thành "Báo giá trước. Không phát sinh." Việc gì cần làm tiếp để câu này thật sự có giá trị?',
    options:[{k:'a',t:'In câu thật to trên biển và áo đồng phục của tất cả nhân viên'},{k:'b',t:'Chạy quảng cáo Facebook với câu này trong ít nhất ba tháng liền'},
             {k:'c',t:'Dịch câu sang tiếng Anh để khách du lịch cũng hiểu lời hứa'},{k:'d',t:'Có quy trình báo giá bằng phiếu và luật xử lý khi phát sinh tại cả năm tiệm'}],
    answer:'d', why:{a:'In to giúp khách thấy, nhưng nếu tiệm không giữ lời thì câu càng to càng hại.',
      b:'Quảng cáo nhân lời hứa lên; nếu vận hành chưa giữ được thì quảng cáo nhân cả lời thất hứa.',
      c:'Có thể hữu ích với khách du lịch, nhưng không phải việc quyết định giá trị của lời hứa.',
      d:'Đúng. Lời hứa chỉ có giá trị khi vận hành giữ được nó ở mọi cửa hàng.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tp03-05', skill:'creative', read:'6 phút', t:'Slogan này đối thủ dán vào có đúng không?',
  situation:'Một thương hiệu gạo đóng túi ở Cần Thơ trình ba phương án slogan: "Hạt ngọc trời ban", "Chất lượng tạo nên niềm tin", và "Gạo mới xay trong 7 ngày, in ngày xay trên túi". Giám đốc thích câu thứ hai vì "nghe chắc chắn". Bạn được nhờ chọn.',
  concept:{ name:'Phép thử dán tên đối thủ',
    body:'Lấy slogan của bạn, bỏ tên bạn đi, dán tên đối thủ vào. Nếu câu vẫn đúng và vẫn nghe hợp lý, <b>slogan đó không thuộc về bạn</b> — nó thuộc về cả ngành. Câu chung chung ("chất lượng", "uy tín", "tận tâm") qua được mọi thương hiệu nên không giúp khách chọn ai. Câu qua được phép thử thường chứa một điều cụ thể mà chỉ bạn đang làm, hoặc bạn làm trước và rõ nhất: một con số, một cách làm, một cam kết.' },
  example:'Dán tên hãng gạo khác vào "Chất lượng tạo nên niềm tin": vẫn đúng — hãng nào cũng muốn nói vậy. "Hạt ngọc trời ban" cũng thế, lại là cách gọi chung của lúa gạo. "Gạo mới xay trong 7 ngày, in ngày xay trên túi" thì đối thủ chỉ dán vào được nếu họ thật sự làm như vậy — và khách kiểm tra được bằng cách nhìn túi. Đó là câu thuộc về bạn.',
  takeaway:'Slogan mà đối thủ dán vào vẫn đúng là slogan của cả ngành, không phải của bạn.',
  apply:'Lấy slogan của thương hiệu bạn, thay bằng tên đối thủ lớn nhất. Nói trong 60 giây: câu còn đúng không, và nếu còn thì thêm điều cụ thể gì.',
  mistakes:['Chọn câu "nghe chắc chắn" mà quên rằng ai cũng nói được câu đó.','Tưởng câu chung chung là an toàn; thực ra nó an toàn vì không nói gì.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong ba câu của hãng gạo, câu nào đối thủ khó dán tên vào nhất?',
    options:[{k:'a',t:'"Hạt ngọc trời ban", vì nó nghe thơ và giàu hình ảnh'},{k:'b',t:'"Gạo mới xay trong 7 ngày, in ngày xay trên túi"'},
             {k:'c',t:'"Chất lượng tạo nên niềm tin", vì nghe chắc chắn nhất'},{k:'d',t:'Cả ba câu đều khó dán như nhau vì đều là câu riêng của hãng'}],
    answer:'b', why:{a:'"Hạt ngọc trời" là cách gọi chung của lúa gạo; ai cũng dùng được.',
      b:'Đúng. Câu chứa một cách làm cụ thể và kiểm tra được; đối thủ chỉ dán được nếu họ cũng làm y như vậy.',
      c:'"Chất lượng" và "niềm tin" là từ chung của mọi ngành.',
      d:'Một câu do hãng viết ra không có nghĩa là câu đó thuộc về hãng.'} },
  { type:'mcq', stem:'Giám đốc vẫn thích "Chất lượng tạo nên niềm tin". Bạn đề xuất gì?',
    options:[{k:'a',t:'Chiều giám đốc, rồi chạy thêm quảng cáo để câu này thành của riêng mình'},{k:'b',t:'Đặt hai câu cạnh nhau trên túi để vừa chắc chắn vừa cụ thể'},
             {k:'c',t:'Làm phép dán tên đối thủ ngay trong buổi họp, rồi chọn câu có ngày xay'},{k:'d',t:'Tìm một câu thứ tư có vần hơn, vì cả ba câu đều chưa hay'}],
    answer:'c', why:{a:'Quảng cáo không biến một câu cả ngành dùng được thành của riêng bạn; tiền trôi sang đối thủ.',
      b:'Hai câu cạnh nhau làm câu cụ thể bị pha loãng bởi câu chung chung.',
      c:'Đúng. Để giám đốc tự thấy câu nào qua được phép thử thuyết phục hơn mọi lập luận.',
      d:'Vần không phải vấn đề; câu có ngày xay đã có điều cụ thể, chỉ cần giữ.'} },
  { type:'mcq', stem:'Slogan nào dưới đây qua được phép dán tên đối thủ tốt nhất?',
    options:[{k:'a',t:'"Tận tâm phục vụ, uy tín hàng đầu" cho một hãng taxi'},{k:'b',t:'"Đồng hành cùng mọi gia đình Việt" cho một hãng sữa'},
             {k:'c',t:'"Sáng tạo không giới hạn" cho một công ty quảng cáo'},{k:'d',t:'"Đổi trả trong 30 ngày, không cần hoá đơn" cho một shop giày'}],
    answer:'d', why:{a:'Hãng taxi nào cũng nói mình tận tâm, uy tín.',
      b:'Hãng sữa nào cũng muốn "đồng hành cùng gia đình".',
      c:'Công ty quảng cáo nào cũng nói mình sáng tạo.',
      d:'Đúng. Một chính sách cụ thể, đối thủ chỉ dán vào được nếu dám làm y như vậy.'} },
  { type:'mcq', stem:'Vì sao câu chung chung như "Uy tín tạo thương hiệu" gần như không giúp khách chọn?',
    options:[{k:'a',t:'Vì khách không cho nó là căn cứ để chọn: hãng nào cũng tự nhận như vậy'},{k:'b',t:'Vì câu quá ngắn nên khách không đọc được trên biển quảng cáo ngoài trời'},
             {k:'c',t:'Vì khách Việt không thích những câu có chữ "thương hiệu" trong đó'},{k:'d',t:'Vì câu chung chung dễ bị cơ quan quản lý yêu cầu chứng minh bằng giấy tờ'}],
    answer:'a', why:{a:'Đúng. Điều ai cũng nói thì không phân biệt được ai; khách bỏ qua như tiếng ồn nền.',
      b:'Câu ngắn thường dễ đọc hơn, không khó hơn.',
      c:'Không có căn cứ cho sở thích từ ngữ như vậy.',
      d:'Đừng suy đoán quy định; vấn đề ở đây là câu không tạo khác biệt.'} },
  { type:'mcq', stem:'Một chuỗi phở dùng câu "Nước dùng ninh 12 tiếng". Hai năm sau, ba chuỗi khác cũng in đúng câu đó. Điều gì nên làm?',
    options:[{k:'a',t:'Kiện ngay cả ba chuỗi vì đã sao chép slogan của mình'},{k:'b',t:'Đổi con số lên "ninh 24 tiếng" để lại khác biệt so với đối thủ'},
             {k:'c',t:'Tìm điều cụ thể mới chỉ mình làm, hoặc gắn câu chặt hơn với tài sản riêng'},{k:'d',t:'Bỏ slogan vì câu đã bị dùng chung và không cứu được'}],
    answer:'c', why:{a:'Chuyện pháp lý cần tra cứu và hỏi người có chuyên môn; không phải phản xạ đầu tiên, và chưa chắc có cơ sở.',
      b:'Chạy đua con số dễ bị đuổi theo tiếp, và phải giữ được trong vận hành thật.',
      c:'Đúng. Khi điều cụ thể bị sao chép thành chung, cần một điều cụ thể mới hoặc cách nói gắn với dấu hiệu riêng.',
      d:'Không cần bỏ hẳn; câu vẫn đúng, chỉ không còn phân biệt — cần bổ sung, không cần xoá.'} },
  { type:'mcq', stem:'Một thương hiệu nước suối muốn qua phép dán tên đối thủ. Hướng nào có khả năng nhất?',
    options:[{k:'a',t:'Thêm các từ "tinh khiết", "trong lành", "tự nhiên" vào câu slogan'},{k:'b',t:'Viết câu thật dài, liệt kê đủ mọi ưu điểm của sản phẩm cùng lúc'},
             {k:'c',t:'Dùng câu của một thương hiệu nước ngoài nổi tiếng rồi dịch sang tiếng Việt'},{k:'d',t:'Nói rõ nguồn nước cụ thể của mình, nơi khác không lấy được'}],
    answer:'d', why:{a:'Nước suối nào cũng tự nhận tinh khiết; từ này thuộc về cả ngành.',
      b:'Danh sách dài không có trọng tâm; khách không nhớ nổi.',
      c:'Mượn câu người khác thì càng không thuộc về mình.',
      d:'Đúng. Một nguồn cụ thể là điều chỉ bạn có; đối thủ dán vào thì sai ngay.'} },
  { type:'mcq', stem:'Phép dán tên đối thủ có giới hạn gì cần nhớ?',
    options:[{k:'a',t:'Chỉ dùng được cho thương hiệu lớn, không dùng được cho cửa hàng nhỏ'},{k:'b',t:'Qua được phép thử chưa đủ: câu còn phải là điều khách thật sự quan tâm'},
             {k:'c',t:'Chỉ dùng được cho slogan tiếng Việt, không áp dụng cho câu tiếng Anh'},{k:'d',t:'Phép thử chỉ đúng khi cả ngành có ít hơn năm đối thủ cạnh tranh trực tiếp'}],
    answer:'b', why:{a:'Cửa hàng nhỏ cũng có đối thủ; phép thử dùng được ở mọi quy mô.',
      b:'Đúng. Một câu có thể rất riêng nhưng nói điều khách không quan tâm — riêng mà vô dụng.',
      c:'Ngôn ngữ không ảnh hưởng tới logic của phép thử.',
      d:'Không có ngưỡng số đối thủ nào như vậy.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tp03-06', skill:'brand', read:'7 phút', t:'Lời hứa "giao trong 30 phút" — vận hành có giữ được không?',
  situation:'Một chuỗi cơm tấm giao hàng ở Hà Nội định in lên hộp và chạy quảng cáo câu "Giao trong 30 phút, trễ tặng nước". Bạn kéo số liệu tháng trước: 2.000 đơn, 340 đơn giao quá 30 phút, phần lớn rơi vào giờ trưa 11h30–12h30 và những ngày mưa.',
  concept:{ name:'Lời hứa thương hiệu phải đi qua được vận hành',
    body:'Lời hứa thương hiệu không nằm ở câu chữ mà nằm ở <b>những lần khách trải nghiệm nó</b>. Mỗi lần thất hứa làm mất niềm tin nhiều hơn một lần giữ lời tạo ra, vì khách nhớ lần thất vọng rõ hơn. Trước khi công bố, hãy đo tỉ lệ giữ được lời hứa hiện tại, tìm chỗ hay vỡ, và quyết định: sửa vận hành cho kịp, hay thu hẹp lời hứa về mức giữ được (theo khu vực, theo khung giờ). Quảng cáo không tạo ra lời hứa — nó chỉ nhân lời hứa lên, kể cả khi lời hứa đang vỡ.' },
  example:'340 trên 2.000 đơn trễ, tức 17% đơn thất hứa — gần một phần sáu. Nếu in lên hộp, cứ sáu khách thì một người nhận hộp ghi "30 phút" trong khi đã chờ lâu hơn. Chỗ vỡ tập trung ở giờ trưa và ngày mưa. Hai lựa chọn hợp lý: thêm shipper ca trưa rồi đo lại, hoặc hứa hẹp hơn, ví dụ "30 phút trong bán kính 3 km, ngoài giờ cao điểm". Trong lúc chưa đạt, chưa nên in lời hứa lên bao bì — thứ khó thu hồi nhất.',
  takeaway:'Đo tỉ lệ giữ lời trước khi in lời hứa; quảng cáo nhân cả lời hứa lẫn lời thất hứa.',
  apply:'Chọn một lời hứa thương hiệu bạn đang nói. Nói trong 60 giây: đo nó bằng số nào, và tháng trước giữ được bao nhiêu phần trăm.',
  mistakes:['Viết lời hứa theo điều khách muốn nghe, không theo điều vận hành làm được.','Tính tỉ lệ trễ trên số đơn giờ thấp điểm, che mất chỗ hay vỡ nhất.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trước khi in câu "Giao trong 30 phút" lên hộp, việc gì quan trọng nhất?',
    options:[{k:'a',t:'Thiết kế câu thật nổi bật trên nắp hộp để khách chụp ảnh chia sẻ'},{k:'b',t:'Hỏi ý kiến khách xem họ thích câu này hay câu "Giao siêu tốc" hơn'},
             {k:'c',t:'Đo xem tháng trước bao nhiêu phần trăm đơn thật sự giao kịp 30 phút'},{k:'d',t:'So với đối thủ xem họ hứa bao nhiêu phút để hứa nhanh hơn'}],
    answer:'c', why:{a:'Thiết kế chỉ làm lời hứa dễ thấy hơn; nếu hay vỡ thì lời thất hứa cũng dễ thấy hơn.',
      b:'Khách luôn thích nghe hứa nhanh; câu hỏi là mình có làm được không.',
      c:'Đúng. Tỉ lệ giữ lời hiện tại cho biết lời hứa là thật hay là rủi ro.',
      d:'Hứa nhanh hơn đối thủ mà không giữ được thì chỉ thua nặng hơn.'} },
  { type:'mcq', stem:'Số liệu cho thấy đơn trễ dồn vào giờ trưa và ngày mưa. Nếu là marketer, bạn chọn làm gì?',
    options:[{k:'a',t:'Chưa in lên hộp; sửa ca trưa hoặc thu hẹp lời hứa rồi đo lại một tháng'},{k:'b',t:'In ngay, vì tặng nước khi trễ đã đủ bù đắp cho khách bị giao chậm'},
             {k:'c',t:'Đổi thành "Giao siêu tốc" để không bị ràng buộc bởi con số cụ thể nào'},{k:'d',t:'In lên hộp nhưng chỉ chạy quảng cáo vào giờ thấp điểm và ngày nắng cho an toàn'}],
    answer:'a', why:{a:'Đúng. Sửa chỗ vỡ hoặc hứa hẹp lại, rồi mới đưa lời hứa lên thứ khó thu hồi.',
      b:'Món quà bù không xoá được cảm giác bị thất hứa, và chi phí bù nhân lên theo số đơn trễ.',
      c:'Bỏ con số là bỏ luôn thứ làm lời hứa đáng tin; "siêu tốc" thành câu chung chung.',
      d:'Hộp in sẵn vẫn đến tay khách giờ trưa; quảng cáo tránh giờ không tránh được lời hứa trên hộp.'} },
  { type:'calc', stem:'Tháng trước có 2.000 đơn, trong đó 340 đơn giao quá 30 phút. Tỉ lệ đơn giữ được lời hứa 30 phút là bao nhiêu phần trăm?',
    unit:'%', ans:83, tol:0.1, wrong:[[17,'SAI_TINH_TOAN'],[85,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Số đơn đúng hẹn = 2.000 − 340 = 1.660.','Tỉ lệ giữ lời = 1.660 ÷ 2.000 = 0,83 = <b>83%</b>.'] },
  { type:'mcq', stem:'Vì sao một lần thất hứa thường tốn niềm tin hơn một lần giữ lời tạo ra?',
    options:[{k:'a',t:'Vì khách chỉ nhớ những đơn có món quà bù, quên hết các đơn đúng hẹn'},{k:'b',t:'Vì lần thất vọng đi ngược kỳ vọng nên được nhớ và kể lại rõ hơn'},
             {k:'c',t:'Vì khách luôn đánh giá một sao ngay lập tức khi đơn bị trễ vài phút'},{k:'d',t:'Vì giữ lời là việc đương nhiên nên khách không nhận ra được bao giờ'}],
    answer:'b', why:{a:'Món quà bù không phải lý do; cơ chế nằm ở kỳ vọng bị phá vỡ.',
      b:'Đúng. Lời hứa dựng kỳ vọng; thất hứa là cú hụt so với kỳ vọng đó nên dễ nhớ và dễ kể.',
      c:'"Luôn" là quá tuyệt đối; không phải khách nào cũng đánh giá.',
      d:'Khách có nhận ra, nhưng một lần đúng hẹn ít đáng kể lại hơn một lần trễ.'} },
  { type:'mcq', stem:'Một spa hứa "Không bao giờ để khách chờ quá 10 phút", nhưng cuối tuần luôn đông. Cách sửa lời hứa nào hợp lý nhất?',
    options:[{k:'a',t:'Giữ nguyên câu và nhắc nhân viên làm nhanh hơn vào cuối tuần'},{k:'b',t:'Đổi thành "Dịch vụ tận tâm" để không còn con số nào có thể bị vi phạm'},
             {k:'c',t:'Tặng voucher cho khách chờ lâu và giữ nguyên câu hứa như cũ'},{k:'d',t:'Hứa theo điều kiện giữ được: đúng giờ cho khách đặt lịch trước'}],
    answer:'d', why:{a:'Nhắc nhở không thêm được ghế và người; lời hứa vẫn vỡ mỗi cuối tuần.',
      b:'Bỏ con số thì lời hứa không còn kiểm tra được — thành câu chung chung.',
      c:'Voucher bù đắp chứ không sửa được; lời hứa vẫn vỡ đều đặn.',
      d:'Đúng. Thu hẹp lời hứa về điều kiện vận hành giữ được, và còn kéo khách đặt lịch trước.'} },
  { type:'mcq', stem:'Sau khi thêm shipper ca trưa, tỉ lệ đúng hẹn lên 96%. Giờ quảng cáo đóng vai trò gì với lời hứa?',
    options:[{k:'a',t:'Nhân lời hứa lên cho nhiều người biết, vì giờ trải nghiệm đã khớp'},{k:'b',t:'Thay thế cho vận hành, vì khách chỉ nhớ quảng cáo chứ ít nhớ đơn hàng'},
             {k:'c',t:'Không cần nữa, vì lời hứa tốt sẽ tự lan truyền mà không cần tiền'},{k:'d',t:'Chỉ nên quảng cáo cho khách cũ, vì khách mới chưa tin lời hứa này'}],
    answer:'a', why:{a:'Đúng. Khi lời hứa đã đứng vững, quảng cáo nhân nó lên mà không nhân thêm thất vọng.',
      b:'Quảng cáo không thay được vận hành; trải nghiệm thật mới là thứ khách mang theo.',
      c:'Truyền miệng có giúp, nhưng thường không đủ nhanh để thay việc quảng cáo tới khách mới.',
      d:'Khách mới chính là nhóm cần nghe lời hứa nhất; khách cũ đã tự trải nghiệm.'} },
  { type:'mcq', stem:'Ai trong công ty cần biết và đồng ý với lời hứa thương hiệu trước khi nó được công bố?',
    options:[{k:'a',t:'Chỉ phòng marketing, vì slogan và lời hứa là việc của marketing'},{k:'b',t:'Chỉ giám đốc, vì giám đốc chịu trách nhiệm cuối cùng về thương hiệu'},
             {k:'c',t:'Những bộ phận làm ra trải nghiệm đó: vận hành, bếp, giao hàng'},{k:'d',t:'Chỉ agency quảng cáo, vì họ viết câu và chạy chiến dịch'}],
    answer:'c', why:{a:'Marketing viết lời hứa, nhưng không phải là người giữ lời hứa mỗi ngày.',
      b:'Giám đốc duyệt, nhưng người làm ra từng đơn mới quyết định lời hứa có đứng được hay không.',
      c:'Đúng. Người giữ lời hứa là người làm ra trải nghiệm; họ phải biết và đồng ý là làm được.',
      d:'Agency không vận hành bếp hay đội giao hàng.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tp03-07', skill:'brand', read:'6 phút', t:'Sếp mới muốn đổi slogan — khi nào đổi mới là đúng?',
  situation:'Một thương hiệu nước giặt nội địa dùng câu "Sạch thơm cả tuần" suốt tám năm. Giám đốc marketing mới về, thấy câu "cũ và nhàm", muốn thay bằng câu mới trong chiến dịch sắp tới. Khảo sát nhỏ cho thấy nhiều khách vẫn nhắc đúng câu này khi được hỏi về thương hiệu.',
  concept:{ name:'Nhàm với người làm, mới với người mua',
    body:'Người trong công ty gặp slogan mỗi ngày nên thấy nhàm rất sớm; khách chỉ gặp nó vài lần một tháng, nên với họ câu vẫn đang được "học". Một slogan được nhớ là <b>tài sản tích luỹ</b>; đổi là xoá tài sản đó và bắt đầu lại. Đổi đúng khi: lời hứa cũ không còn đúng (sản phẩm đổi, vận hành không giữ được), lời hứa không còn quan trọng với khách, hoặc thương hiệu đổi hướng chiến lược thật. Không nên đổi chỉ vì người mới muốn để lại dấu ấn, hay vì nội bộ thấy chán.' },
  example:'"Sạch thơm cả tuần" vẫn đúng với sản phẩm, vẫn là điều khách mua nước giặt quan tâm, và khách vẫn nhắc đúng — cả ba lý do đổi đều không có. Cái giám đốc mới cảm thấy là nhàm của người trong cuộc. Việc hợp lý hơn: giữ câu, làm mới cách thể hiện — hình ảnh mới, tình huống mới, bằng chứng mới cho cùng một lời hứa.',
  takeaway:'Đổi slogan khi lời hứa sai hoặc hết giá trị, không phải khi người trong công ty thấy chán.',
  apply:'Nghĩ về một thương hiệu đã đổi slogan gần đây. Nói trong 60 giây: lý do đổi là lời hứa hết đúng, hết quan trọng, hay chỉ là nội bộ muốn mới.',
  mistakes:['Lấy cảm giác nhàm của nội bộ làm căn cứ đổi slogan.','Đổi slogan mỗi chiến dịch, khiến khách không kịp nhớ câu nào.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao người trong công ty thường thấy slogan nhàm sớm hơn khách rất nhiều?',
    options:[{k:'a',t:'Vì người trong công ty có gu thẩm mỹ cao hơn khách hàng bình thường'},{k:'b',t:'Vì slogan thường được viết vội nên vốn đã nhàm từ khi ra đời'},
             {k:'c',t:'Vì khách không bao giờ để ý tới slogan nên không có cảm giác gì'},{k:'d',t:'Vì họ gặp câu đó mỗi ngày, còn khách chỉ gặp thỉnh thoảng'}],
    answer:'d', why:{a:'Không phải chuyện gu; đây là chuyện tần suất tiếp xúc.',
      b:'Nhiều câu được viết rất kỹ vẫn bị nội bộ chán sau vài năm.',
      c:'"Không bao giờ" là sai; khảo sát cho thấy khách vẫn nhắc đúng câu.',
      d:'Đúng. Tần suất tiếp xúc chênh nhau rất xa; khách vẫn đang học câu mà nội bộ đã thuộc lòng.'} },
  { type:'mcq', stem:'Giám đốc mới muốn đổi "Sạch thơm cả tuần". Bạn đề xuất gì?',
    options:[{k:'a',t:'Đổi sang câu mới cho hợp với phong cách của giám đốc mới'},{k:'b',t:'Giữ câu, làm mới cách thể hiện bằng hình ảnh và bằng chứng mới'},
             {k:'c',t:'Dùng song song câu cũ và câu mới trong một năm để so sánh'},{k:'d',t:'Hỏi ý kiến toàn bộ nhân viên rồi đổi theo câu được bầu nhiều nhất'}],
    answer:'b', why:{a:'Phong cách người làm không phải lý do; câu cũ vẫn đúng, vẫn được nhớ.',
      b:'Đúng. Giữ tài sản đã tích luỹ, đổi phần khách thấy mới: cách kể và bằng chứng.',
      c:'Hai câu song song chia đôi trí nhớ và làm yếu cả hai.',
      d:'Nhân viên chính là nhóm thấy nhàm nhất; bầu chọn nội bộ sẽ nghiêng về đổi.'} },
  { type:'mcq', stem:'Trường hợp nào đổi slogan là có căn cứ?',
    options:[{k:'a',t:'Sản phẩm đổi công thức, lời hứa cũ không còn đúng với thực tế'},{k:'b',t:'Slogan đã dùng năm năm và đội marketing muốn một câu mới hơn'},
             {k:'c',t:'Đối thủ vừa ra slogan mới, mình cũng cần đổi để không bị lép vế'},{k:'d',t:'Agency mới được thuê và muốn đề xuất một câu khẳng định dấu ấn'}],
    answer:'a', why:{a:'Đúng. Lời hứa sai với sản phẩm thì phải sửa, dù câu đang được nhớ.',
      b:'Thời gian dùng lâu là tài sản, không phải lý do đổi.',
      c:'Đối thủ đổi câu không làm lời hứa của bạn sai hay hết giá trị.',
      d:'Nhu cầu để lại dấu ấn của agency không phải lý do của khách.'} },
  { type:'mcq', stem:'Một thương hiệu đổi slogan ba lần trong ba năm. Hậu quả dễ thấy nhất là gì?',
    options:[{k:'a',t:'Khách thấy thương hiệu năng động nên mua nhiều hơn qua từng năm'},{k:'b',t:'Chi phí in ấn tăng mạnh nên lợi nhuận giảm theo từng năm'},
             {k:'c',t:'Khách không kịp nhớ câu nào, thương hiệu không tích luỹ được lời hứa'},{k:'d',t:'Nhân viên phải học lại câu mới nên phục vụ khách chậm hơn'}],
    answer:'c', why:{a:'Không có căn cứ rằng đổi câu liên tục làm khách mua nhiều hơn.',
      b:'Chi phí in có tăng, nhưng thiệt hại lớn hơn nằm ở trí nhớ của khách.',
      c:'Đúng. Mỗi lần đổi là bắt đầu lại từ đầu; không câu nào đủ lâu để thành tài sản.',
      d:'Học câu mới không làm chậm phục vụ; đây không phải hậu quả chính.'} },
  { type:'mcq', stem:'Muốn biết slogan có còn làm việc hay không, nên xem dấu hiệu nào?',
    options:[{k:'a',t:'Số lượt thích của bài đăng giới thiệu slogan trên fanpage'},{k:'b',t:'Khách có nhắc lại đúng câu và gắn đúng với thương hiệu không'},
             {k:'c',t:'Cảm nhận của ban giám đốc sau khi đọc lại câu slogan'},{k:'d',t:'Số lần slogan xuất hiện trong các tài liệu nội bộ công ty'}],
    answer:'b', why:{a:'Lượt thích một bài đăng đo phản ứng tức thời, không đo trí nhớ gắn với thương hiệu.',
      b:'Đúng. Slogan làm việc khi khách nhớ câu và nhớ câu đó của ai.',
      c:'Cảm nhận nội bộ chính là thứ dễ lệch nhất so với khách.',
      d:'Tài liệu nội bộ không cho biết gì về trí nhớ của khách.'} },
  { type:'mcq', stem:'Hãng nước giặt ra dòng mới giặt được bằng nước lạnh, và đây là điều khách đang tìm. Nên xử lý slogan thế nào?',
    options:[{k:'a',t:'Giữ lời hứa chính, nói điểm mới trong truyền thông của dòng sản phẩm'},{k:'b',t:'Đổi slogan chính thành "Giặt nước lạnh" để cả thương hiệu theo ý mới'},
             {k:'c',t:'Ghép thành "Sạch thơm cả tuần, giặt nước lạnh" cho đủ cả hai ý'},{k:'d',t:'Bỏ slogan, để mỗi dòng sản phẩm tự nói lời hứa riêng của mình'}],
    answer:'a', why:{a:'Đúng. Lời hứa chính vẫn đúng; điểm mới của một dòng không đủ lý do xoá câu của cả thương hiệu.',
      b:'Đổi câu chính theo một dòng có thể làm lệch cả thương hiệu và xoá tài sản cũ.',
      c:'Câu ghép dài và hứa hai điều; khách khó nhớ trọng tâm.',
      d:'Bỏ câu chính là bỏ tài sản chung mà mọi dòng đang dựa vào.'} },
  { type:'mcq', stem:'Nếu buộc phải đổi slogan, cách làm nào giữ được nhiều tài sản cũ nhất?',
    options:[{k:'a',t:'Đổi hết cùng lúc: tên, logo, màu và câu để tạo cú hích lớn'},{k:'b',t:'Đổi câu nhưng im lặng, không nói gì để khách tự nhận ra sự khác biệt'},
             {k:'c',t:'Chọn câu mới hoàn toàn khác để khách biết thương hiệu đã thay đổi'},{k:'d',t:'Giữ các dấu hiệu nhận diện khác, chuyển dần và lặp câu mới đủ lâu'}],
    answer:'d', why:{a:'Đổi mọi thứ một lúc là xoá hết mọi móc trí nhớ khách đang dùng để nhận ra bạn.',
      b:'Im lặng không giúp khách nối câu mới với thương hiệu cũ.',
      c:'Khác hoàn toàn nghĩa là không có gì từ câu cũ được mang sang.',
      d:'Đúng. Giữ phần khách đang nhận ra, để câu mới dựa vào đó mà lớn dần.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tp03-08', skill:'brand', read:'7 phút', t:'Sản phẩm con mới nên mang tên mẹ hay có tên riêng?',
  situation:'Một thương hiệu mỹ phẩm thiên nhiên nổi tiếng với dòng dầu gội bồ kết, định ra thêm hai sản phẩm: một kem chống nắng cho da mặt và một dòng xịt côn trùng cho gia đình. Đội sản phẩm đề xuất đặt tên riêng thật kêu cho từng món. Đội bán hàng muốn tất cả đều mang tên thương hiệu mẹ.',
  concept:{ name:'Kiến trúc thương hiệu',
    body:'Có ba cách chính. <b>Một nhà</b>: mọi sản phẩm mang tên mẹ (như Vinamilk với nhiều dòng sữa) — món mới hưởng ngay niềm tin cũ, nhưng món hỏng làm vạ lây cả nhà. <b>Nhiều nhà</b>: mỗi sản phẩm có tên riêng, không lộ tên mẹ — linh hoạt, tách rủi ro, nhưng mỗi tên phải tự xây từ đầu. <b>Bảo chứng</b>: tên riêng kèm dòng nhỏ "của [tên mẹ]" — vừa có cá tính riêng vừa mượn được niềm tin. Câu hỏi quyết định: khách có thấy hợp lý khi món mới đến từ cùng một nhà không.' },
  example:'Kem chống nắng thiên nhiên nằm gần lời hứa hiện tại của thương hiệu — chăm sóc cơ thể bằng nguyên liệu lành. Mang tên mẹ là hợp lý và tiết kiệm. Xịt côn trùng thì khác: khách có thể thấy lạ khi hãng dầu gội bán thuốc xịt, và nếu sản phẩm có sự cố, tên mẹ bị ảnh hưởng. Cách bảo chứng hoặc tên riêng hẳn an toàn hơn cho món này. Một nguyên tắc cho cả hai: đừng đặt tên riêng chỉ vì "nghe kêu".',
  takeaway:'Món mới càng gần lời hứa của thương hiệu mẹ thì càng nên mang tên mẹ; càng xa thì càng nên tách.',
  apply:'Chọn một hãng bạn biết có nhiều dòng sản phẩm. Nói trong 60 giây: họ dùng một nhà, nhiều nhà hay bảo chứng, và vì sao.',
  mistakes:['Đặt tên riêng cho mọi món mới, tự chia nhỏ ngân sách xây nhiều thương hiệu cùng lúc.','Gắn tên mẹ lên món rất xa ngành, làm lời hứa gốc bị loãng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì nên quyết định sản phẩm mới mang tên mẹ hay tên riêng?',
    options:[{k:'a',t:'Món mới gần hay xa lời hứa mà khách đang gắn với thương hiệu mẹ'},{k:'b',t:'Tên riêng nào nghe kêu hơn thì dùng tên riêng cho món đó'},
             {k:'c',t:'Sản phẩm nào có giá cao hơn thì nên có tên riêng để trông sang'},{k:'d',t:'Đội bán hàng muốn cách nào thì làm theo cách đó cho dễ chào hàng'}],
    answer:'a', why:{a:'Đúng. Khoảng cách giữa món mới và lời hứa gốc quyết định mượn niềm tin có hợp lý không.',
      b:'"Nghe kêu" không trả lời được câu hỏi khách có tin món này không.',
      c:'Giá không phải tiêu chí chính; nhiều hãng bán hàng cao cấp dưới tên mẹ.',
      d:'Đội bán hàng có góc nhìn quan trọng, nhưng tiêu chí phải là cách khách nhìn thương hiệu.'} },
  { type:'mcq', stem:'Nếu là marketer của hãng, bạn chọn cách đặt tên nào cho hai món mới?',
    options:[{k:'a',t:'Cả hai đều mang tên riêng hoàn toàn để thương hiệu mẹ được an toàn'},{k:'b',t:'Cả hai đều mang tên mẹ để tận dụng tối đa niềm tin sẵn có, khỏi tốn tiền xây tên mới'},
             {k:'c',t:'Kem chống nắng mang tên mẹ; xịt côn trùng dùng tên riêng có bảo chứng hoặc tách hẳn'},{k:'d',t:'Hoãn cả hai món cho tới khi có đủ tiền xây một thương hiệu mới'}],
    answer:'c', why:{a:'Tên riêng cho kem chống nắng là bỏ phí niềm tin vốn rất hợp với món này.',
      b:'Tên mẹ trên thuốc xịt côn trùng có thể làm khách thấy lạ và rủi ro lây sang cả nhà.',
      c:'Đúng. Mỗi món một quyết định, theo khoảng cách với lời hứa gốc.',
      d:'Hoãn cả hai là bỏ lỡ món gần lời hứa, vốn có thể ra ngay dưới tên mẹ.'} },
  { type:'mcq', stem:'Cách "nhiều nhà" (mỗi sản phẩm một tên riêng, không lộ tên mẹ) có nhược điểm lớn nhất là gì?',
    options:[{k:'a',t:'Khách không mua được sản phẩm trên các sàn thương mại điện tử'},{k:'b',t:'Sản phẩm dễ bị nhầm với nhau khi nằm cạnh nhau trên kệ hàng'},
             {k:'c',t:'Khó thay đổi bao bì từng sản phẩm khi cần cập nhật thông tin'},{k:'d',t:'Mỗi tên phải tự xây nhận biết từ đầu, tốn tiền nhân lên theo số tên'}],
    answer:'d', why:{a:'Sàn không phân biệt kiến trúc thương hiệu; đây không phải nhược điểm.',
      b:'Tên riêng thường khác nhau rõ, nên ít bị nhầm hơn.',
      c:'Bao bì từng món vẫn sửa được độc lập; đó thậm chí là lợi thế.',
      d:'Đúng. Không mượn được niềm tin của ai, nên mỗi tên là một khoản đầu tư riêng.'} },
  { type:'mcq', stem:'Một hãng sữa ra dòng sữa hạt cao cấp, đặt tên riêng kèm dòng nhỏ "từ [tên hãng]". Đây là cách nào?',
    options:[{k:'a',t:'Một nhà, vì vẫn có tên hãng mẹ xuất hiện trên bao bì sản phẩm'},{k:'b',t:'Bảo chứng: tên riêng có cá tính, tên mẹ đứng sau để mượn niềm tin'},
             {k:'c',t:'Nhiều nhà, vì sản phẩm có tên riêng khác hẳn tên của hãng mẹ'},{k:'d',t:'Thương hiệu con độc lập, vì đây là một dòng cao cấp mới ra đời'}],
    answer:'b', why:{a:'Một nhà là khi tên mẹ là tên chính; ở đây tên chính là tên riêng.',
      b:'Đúng. Tên riêng dẫn đầu, tên mẹ bảo lãnh ở vị trí phụ.',
      c:'Nhiều nhà là khi tên mẹ không xuất hiện; ở đây tên mẹ có mặt.',
      d:'"Độc lập" nghĩa là không dựa vào tên mẹ; dòng bảo chứng thì có dựa.'} },
  { type:'mcq', stem:'Một thương hiệu một nhà có một sản phẩm bị khách phản ánh nhiều trên mạng. Rủi ro đặc thù của cách một nhà ở đây là gì?',
    options:[{k:'a',t:'Hãng không thể thu hồi sản phẩm lỗi vì dùng chung một tên thương hiệu'},{k:'b',t:'Khách sẽ chỉ nhớ tên sản phẩm lỗi, quên hẳn tên hãng mẹ'},
             {k:'c',t:'Ấn tượng xấu có thể lan sang những sản phẩm khác cùng tên'},{k:'d',t:'Các sàn thương mại điện tử sẽ gỡ toàn bộ sản phẩm cùng tên'}],
    answer:'c', why:{a:'Việc thu hồi không phụ thuộc vào kiến trúc tên.',
      b:'Ngược lại: vì cùng tên, khách gắn chuyện đó với cả hãng.',
      c:'Đúng. Dùng chung tên thì chung cả niềm tin lẫn rủi ro.',
      d:'Đây là suy đoán không có căn cứ về chính sách sàn.'} },
  { type:'mcq', stem:'Đội sản phẩm muốn đặt tên riêng "thật kêu" cho mọi món, kể cả một chai dầu gội bồ kết mới mùi bưởi. Góp ý nào đúng?',
    options:[{k:'a',t:'Hợp lý, vì mỗi mùi mới cần một cá tính riêng để nổi bật trên kệ'},{k:'b',t:'Hợp lý, vì tên kêu giúp món mới bán giá cao hơn dòng cũ ngay lập tức'},
             {k:'c',t:'Chỉ đặt tên riêng khi món mới được bán ở một kênh phân phối khác'},{k:'d',t:'Một biến thể mùi của dòng chủ lực nên nằm dưới tên dòng, chỉ đổi phần mô tả'}],
    answer:'d', why:{a:'Mùi mới là biến thể; tạo cá tính riêng cho nó là chia nhỏ trí nhớ của khách.',
      b:'Giá cao không đến từ tên kêu; khách mua dầu gội này vì tin dòng bồ kết.',
      c:'Kênh phân phối khác không phải lý do đủ để tách tên.',
      d:'Đúng. Biến thể gần nhất thì dựa hẳn vào tên dòng; chỉ phần mô tả (mùi bưởi) là khác.'} },
  { type:'mcq', stem:'Khi nào cách "nhiều nhà" thường đáng đầu tư hơn "một nhà"?',
    options:[{k:'a',t:'Khi các sản phẩm nhắm tới nhóm khách và mức giá khác xa nhau'},{k:'b',t:'Khi công ty có ít tiền marketing và cần tiết kiệm tối đa ngân sách'},
             {k:'c',t:'Khi thương hiệu mẹ đã rất nổi tiếng và được khách tin tưởng'},{k:'d',t:'Khi các sản phẩm rất giống nhau và cùng bán ở một quầy hàng'}],
    answer:'a', why:{a:'Đúng. Một tên khó vừa hứa giá rẻ cho nhóm này vừa hứa cao cấp cho nhóm kia.',
      b:'Ít tiền thì nhiều nhà là tốn nhất, vì mỗi tên phải tự xây.',
      c:'Mẹ đã nổi tiếng thì thường nên tận dụng, trừ khi món mới đi ngược lời hứa.',
      d:'Sản phẩm giống nhau thì chung tên giúp tiết kiệm và dễ nhận ra.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tp03-09', skill:'creative', read:'7 phút', t:'Đặt tên cho chiến dịch sao cho khách nhắc được và nối về thương hiệu?',
  situation:'Một chuỗi siêu thị mini ở Hà Nội chuẩn bị chiến dịch mùa tựu trường, ngân sách 300 triệu. Agency đề xuất tên "Back to School Mega Sale 2026". Sau đợt tương tự năm ngoái, khảo sát 200 khách: 120 người nhớ có chương trình, nhưng chỉ 30 người nói đúng đó là của chuỗi nào.',
  concept:{ name:'Tên chiến dịch phải mang dấu thương hiệu',
    body:'Tên chiến dịch có hai việc: <b>được nhắc</b> (khách nói ra được khi rủ nhau) và <b>được nối</b> (nghe là biết của ai). Tên kiểu "Mega Sale", "Siêu sale tựu trường" làm được việc thứ nhất nhưng không làm việc thứ hai — cả thị trường cùng dùng một kiểu tên, nên khách nhớ có khuyến mãi mà quên của ai. Tên tốt mượn một thứ đã thuộc về thương hiệu (tên, linh vật, màu, câu quen) hoặc một chi tiết riêng của chính chương trình, và nên giữ lặp lại qua nhiều năm để thành một dịp khách chờ.' },
  example:'Năm ngoái 120 trên 200 người nhớ có chương trình, nhưng chỉ 30 người nối đúng về chuỗi — tức 25% người nhớ chương trình biết nó là của ai. Ba phần tư trí nhớ mà 300 triệu mua được đã không gắn vào thương hiệu. Một tên như "Cặp Xanh [tên chuỗi]" mượn màu nhận diện và gắn tên chuỗi ngay trong câu; lặp lại mỗi mùa tựu trường, nó có thể thành dịp khách tự nhắc.',
  takeaway:'Tên chiến dịch khách nhớ mà không biết của ai là tiền quảng cáo cho cả ngành.',
  apply:'Nhớ lại một chiến dịch khuyến mãi bạn thấy gần đây. Nói trong 60 giây: bạn còn nhớ tên nó không, và có nối được về đúng thương hiệu không.',
  mistakes:['Chọn tên chiến dịch theo kiểu cả thị trường đang dùng vì "khách quen rồi".','Mỗi năm đổi một tên mới, không tích luỹ được một dịp khách chờ đợi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với tên "Back to School Mega Sale", điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Khách nhớ có khuyến mãi nhưng không nhớ là của chuỗi nào'},{k:'b',t:'Khách không hiểu tiếng Anh nên hoàn toàn bỏ qua chương trình'},
             {k:'c',t:'Khách nghi ngờ vì chữ "Mega" nghe như giảm giá không thật lòng'},{k:'d',t:'Khách nhớ tên chương trình nhưng không nhớ nó diễn ra khi nào'}],
    answer:'a', why:{a:'Đúng. Tên kiểu chung của thị trường làm được việc "được nhắc" nhưng không "được nối".',
      b:'Nhóm khách thành phố hiểu cụm này khá phổ biến; vấn đề không ở ngôn ngữ.',
      c:'Có thể có chút nghi ngờ, nhưng rủi ro lớn hơn là thiếu dấu thương hiệu.',
      d:'Mùa tựu trường đã gắn sẵn thời điểm; chuyện thời gian không phải vấn đề chính.'} },
  { type:'mcq', stem:'Nếu là marketer của chuỗi, bạn chọn hướng đặt tên nào cho chiến dịch năm nay?',
    options:[{k:'a',t:'Giữ tên của agency nhưng tăng gấp đôi ngân sách hiển thị quảng cáo'},{k:'b',t:'Đổi sang "Siêu Sale Tựu Trường" cho thuần Việt và dễ đọc hơn'},
             {k:'c',t:'Mỗi cửa hàng tự đặt một tên riêng cho hợp với khách ở khu vực mình'},{k:'d',t:'Một tên gắn tài sản riêng của chuỗi, và dùng lại cho mùa sau'}],
    answer:'d', why:{a:'Tăng tiền cho một tên không nối về chuỗi là mua thêm trí nhớ cho cả ngành.',
      b:'Thuần Việt dễ đọc hơn, nhưng vẫn là kiểu tên cả thị trường dùng chung.',
      c:'Nhiều tên thì không tên nào đủ mạnh để được nhớ.',
      d:'Đúng. Tên mang dấu thương hiệu làm việc "được nối"; lặp lại làm việc "được nhắc".'} },
  { type:'mcq', stem:'Vì sao nên giữ cùng một tên chiến dịch qua nhiều năm thay vì mỗi năm một tên mới?',
    options:[{k:'a',t:'Vì đặt tên mới tốn phí tra cứu và thủ tục cho mỗi lần làm'},{k:'b',t:'Vì khách sẽ nhận ra chương trình ngay và bắt đầu chờ nó mỗi năm'},
             {k:'c',t:'Vì agency thường tính phí cao hơn khi phải đặt tên mới'},{k:'d',t:'Vì đổi tên thường xuyên sẽ khiến đối thủ nghĩ chuỗi đang gặp khó'}],
    answer:'b', why:{a:'Chi phí thủ tục có thể có, nhưng không phải lý do chính.',
      b:'Đúng. Lặp lại biến một chương trình thành một dịp; khách chờ, rủ nhau, và nhớ của ai.',
      c:'Phí agency không phải lý do chiến lược để giữ tên.',
      d:'Đối thủ nghĩ gì không phải điều đáng tối ưu; trí nhớ của khách mới đáng.'} },
  { type:'calc', stem:'Khảo sát 200 khách: 120 người nhớ có chương trình, trong đó 30 người nói đúng là của chuỗi nào. Trong số người nhớ chương trình, bao nhiêu phần trăm nối đúng về chuỗi?',
    unit:'%', ans:25, tol:0.1, wrong:[[15,'SAI_MAU_SO'],[60,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Mẫu số là số người nhớ chương trình: 120 (không phải 200).','Tỉ lệ nối đúng = 30 ÷ 120 = 0,25 = <b>25%</b>.'] },
  { type:'mcq', stem:'Một hãng trà sữa có linh vật con gấu được khách quen. Tên chiến dịch hè nào có khả năng nối về hãng tốt nhất?',
    options:[{k:'a',t:'Một tên có con gấu, ví dụ "Hè Cùng Gấu", dùng lại mỗi mùa hè'},{k:'b',t:'"Summer Sale Up To 50%" đặt nổi bật trên mọi ấn phẩm của hãng'},
             {k:'c',t:'"Hè Rực Rỡ – Giải Nhiệt Cực Đã" cho khí thế và sôi động'},{k:'d',t:'"Siêu Hội Mùa Hè 2026" đi kèm con số năm để có cảm giác mới'}],
    answer:'a', why:{a:'Đúng. Mượn linh vật đã thuộc về hãng, và lặp lại để thành một dịp.',
      b:'Tên mô tả khuyến mãi chung; hãng nào cũng dùng được.',
      c:'Câu vui nhưng không có gì của riêng hãng.',
      d:'Kiểu tên chung của thị trường; con số năm còn làm tên khó dùng lại.'} },
  { type:'mcq', stem:'Chiến dịch được khách nhắc rất nhiều trên mạng, nhưng doanh số của chuỗi không tăng. Giả thuyết đầu tiên nên kiểm tra là gì?',
    options:[{k:'a',t:'Nội dung quá hài hước nên khách chỉ xem cho vui mà không mua'},{k:'b',t:'Tên chiến dịch quá dài nên khách không đọc được hết trên điện thoại'},
             {k:'c',t:'Khách nhắc chiến dịch nhưng không nối về chuỗi, nên đi mua ở chỗ khác'},{k:'d',t:'Ngân sách quá ít nên không đủ để chiến dịch tạo tác động đáng kể'}],
    answer:'c', why:{a:'Có thể, nhưng khi tên không có dấu thương hiệu, lỗi nối là nghi phạm đầu tiên.',
      b:'Độ dài ảnh hưởng tới việc nhắc; ở đây khách đã nhắc nhiều.',
      c:'Đúng. Được nhắc mà không được nối thì sự chú ý chảy sang cả thị trường.',
      d:'Được nhắc nhiều cho thấy tầm với không phải vấn đề chính.'} },
  { type:'mcq', stem:'Một chiến dịch từ thiện của hãng sữa đặt tên "Vì trẻ em Việt Nam". Góp ý nào có căn cứ nhất?',
    options:[{k:'a',t:'Tên hay vì mang ý nghĩa nhân văn, không cần chỉnh sửa gì thêm'},{k:'b',t:'Nên đổi sang tiếng Anh để chiến dịch có tầm quốc tế hơn'},
             {k:'c',t:'Nên bỏ tên, vì chiến dịch từ thiện thì không cần gắn thương hiệu'},{k:'d',t:'Tên đẹp nhưng ai cũng dùng được; nên gắn thêm dấu riêng của hãng'}],
    answer:'d', why:{a:'Ý nghĩa tốt nhưng không nối về ai; công sức của hãng dễ bị nhớ lẫn với tổ chức khác.',
      b:'Ngôn ngữ không giải quyết việc nối về thương hiệu.',
      c:'Gắn thương hiệu một cách tử tế là hợp lý; đó là cách chiến dịch có thể được duy trì lâu dài.',
      d:'Đúng. Giữ tinh thần nhưng thêm một dấu riêng để khách nhớ ai đang làm việc này.'} }
  ] }

] });
